        rail_c = next((c for c in range(1, w) if grid[min(2, h - 1)][c] != background), 2)
    rail_color = grid[rail_r][rail_c]
    start_r, start_c = rail_r + 1, rail_c + 1

    # Find the shortest exact horizontal period in the longest uninterrupted
    # interior run. The interior has long unmasked stretches in every fixture.
    best = []
    for r in range(start_r, h):
        c = start_c
        while c < w:
            while c < w and grid[r][c] == 0:
                c += 1
            a = c
            while c < w and grid[r][c] != 0:
                c += 1
            run = grid[r][a:c]
            if len(run) > len(best):
                best = run
