            if grid[r][c] != 0:
                continue
            if r < start_r or c < start_c:
                if r < rail_r or c < rail_c:
                    out[r][c] = background
                else:
                    out[r][c] = rail_color
                continue
            # Infer this row's phase by majority agreement with known cells;
            # this accommodates the irregular seed cells near the frame.
            known = [(cc, grid[r][cc]) for cc in range(start_c, w) if grid[r][cc] != 0]
            if known:
                offsets = range(period)
