def _row_model(row, start, max_period=10):
    """Fit the shortest repeating horizontal sequence to known cells."""
    known = [(c, row[c]) for c in range(start, len(row)) if row[c] != 0]
    if not known:
        return None
    best = None
    for period in range(1, min(max_period, len(row) - start) + 1):
        for phase in range(period):
            buckets = defaultdict(list)
            for c, value in known:
                buckets[(c + phase) % period].append(value)
            values = {}
            matches = 0
            for residue, vs in buckets.items():
                counts = Counter(vs)
                value, n = counts.most_common(1)[0]
                values[residue] = value
                matches += n
            # Prefer the simplest period when it explains equally many cells.
            key = (matches, -period)
            if best is None or key > best[0]:
                best = (key, period, phase, values)
    return best[1:]


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    rail = next((v for row in grid for v in row if v not in (bg, 0)), 4)
    pattern_r = 3
    pattern_c = 3

    # Restore the two-cell outer margin and the one-cell top/left frame rails.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < pattern_r and c < pattern_c:
                out[r][c] = rail if r == 2 or c == 2 else bg
            elif r < pattern_r:
                out[r][c] = rail if r == 2 else bg
            elif c < pattern_c:
                out[r][c] = rail if c == 2 else bg

    # The interior is a row-shifted periodic sequence; infer each row's cycle
    # from its intact cells and interpolate the masked cells.
    for r in range(pattern_r, h):
        model = _row_model(grid[r], pattern_c)
        if model is None:
            continue
        period, phase, values = model
        for c in range(pattern_c, w):
            if grid[r][c] == 0:
                out[r][c] = values[(c + phase) % period]
    return out


